import React from "react";
import "./Home.scss";

const Home = () => {
  return (
    <div className="home-container">
      <div className="grid-container">
        {/* Primeira linha */}
        <div className="grid-item large">
          <img src="/assets/image1.jpg" alt="GOMODEN" />
          <div className="overlay">
            <h2>GOMODEN</h2>
            <p>Nebo diente de origine de nuestro proyecto.</p>
            <button>SHOP NOW</button>
          </div>
        </div>

        {/* Segunda linha */}
        <div className="grid-item dark">
          <h2>CORES DA CIDADE</h2>
          <p>Inspirar el nivel donde estamos visitando.</p>
          <button>SHOP NOW</button>
        </div>
        <div className="grid-item light">
          <img src="/assets/image2.jpg" alt="INEDE ANIMALE" />
          <div className="overlay">
            <h2>INEDE ANIMALE</h2>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
